class CmsRedirect { #[ORM\Id,ORM\GeneratedValue,ORM\Column] private ?int $id=null; #[ORM\ManyToOne] #[ORM\JoinColumn(name:'channel_id',referencedColumnName:'id',nullable:false,onDelete:'CASCADE')] private ?Channel $channel=null; #[ORM\Column(length:12)] private string $locale=''; #[ORM\Column(name:'source_path',length:255)] private string $sourcePath=''; #[ORM\ManyToOne] #[ORM\JoinColumn(name:'target_page_id',referencedColumnName:'id',onDelete:'CASCADE')] private ?CmsPage $targetPage=null; #[ORM\Column(name:'target_path',length:255,nullable:true)] private ?string $targetPath=null; #[ORM\Column(name:'status_code')] private int $statusCode=301; #[ORM\Column(name:'created_at',type:Types::DATETIME_IMMUTABLE)] private \DateTimeImmutable $createdAt; public function __construct(){ $this->createdAt=new \DateTimeImmutable();} public function getId():?int{return $this->id;} public function getChannel():?Channel{return $this->channel;} public function setChannel(Channel $v):void{$this->channel=$v;} public function getLocale():string{return $this->locale;} public function setLocale(string $v):void{$this->locale=$v;} public function getSourcePath():string{return $this->sourcePath;} public function setSourcePath(string $v):void{$this->sourcePath=\App\Cms\CmsSlug::normalize($v);} public function getTargetPage():?CmsPage{return $this->targetPage;} public function setTargetPage(?CmsPage $v):void{$this->targetPage=$v;} public function getTargetPath():?string{return $this->targetPath;} public function setTargetPath(?string $v):void{$this->targetPath=$v===null?null:\App\Cms\CmsSlug::normalize($v);} public function getStatusCode():int{return $this->statusCode;} }
